const log = [];

function load(source) {
  log.push('불러오는 중');
  try {
    const data = JSON.parse(source);
    log.push('완료: ' + data.name);
    return data.name;
  } catch (e) {
    log.push('실패: ' + e.name);
    return null;
  } finally {
    null; // ← 여기를 채우세요
  }
}

// 이 함수는 그대로 두세요
function trace(source) {
  log.length = 0;
  load(source);
  return log.join(' / ');
}

